def good_sum_sq(x, y):
    return x**2 + y**2

pairs = []
x = 1
while len(pairs) < 10:
    y = x + 1
    while True:
        if x < y and (x + y) % 2 == 0:
            pairs.append(good_sum_sq(x, y))
            if len(pairs) >= 10:
                break
        y += 1
    x += 1

pairs.sort()
print(pairs)
